// English overlay for the glossary (G.OPH.glossary), keyed by the FR term.
// Each entry is { term: 'English term', def: 'English definition' }; src/i18n.js renames the key to `term`.
var G = (typeof window !== 'undefined') ? window : globalThis;
G.OPH_EN = G.OPH_EN || {};
G.OPH_EN.glossary = G.OPH_EN.glossary || {};

// ---- data/capsules.js ----
Object.assign(G.OPH_EN.glossary, {
  "défaut épithélial": { term: "epithelial defect", def: "Area where the corneal epithelium is missing; it turns green with fluorescein under cobalt blue light." },
  "infiltrat": { term: "infiltrate", def: "Gray-white spot in the stroma made of inflammatory cells; infectious or sterile." },
  "hypopyon": { term: "hypopyon", def: "White layer of white blood cells at the bottom of the anterior chamber, with a horizontal level; intense inflammation, possibly a serious infection." },
  "dendrite": { term: "dendrite", def: "Branching epithelial ulcer with terminal bulbs that takes up fluorescein; the signature of herpes simplex." },
  "pseudodendrite": { term: "pseudodendrite", def: "Elevated branching lesion without terminal bulbs that stains poorly with fluorescein; typical of zoster, also seen with Acanthamoeba." },
  "KP": { term: "KP", def: "Keratic precipitates: clumps of inflammatory cells stuck to the endothelium; a sign of inflammation inside the eye (uveitis, rejection, herpes)." },
  "précipités kératiques": { term: "keratic precipitates", def: "Deposits of inflammatory cells on the inner surface of the cornea (KP); they indicate intraocular inflammation." },
  "plis de Descemet": { term: "Descemet folds", def: "Striae at the back of the cornea when the stroma swells (edema, hypotony, after surgery)." },
  "guttae": { term: "guttae", def: "Small excrescences of Descemet membrane made by a diseased endothelium; dark areas on specular microscopy; a sign of Fuchs dystrophy." },
  "ligne de Khodadoust": { term: "Khodadoust line", def: "Line of keratic precipitates advancing across a graft's endothelium and leaving edematous cornea behind it: endothelial rejection." },
  "rejet endothélial": { term: "endothelial rejection", def: "Immune attack on a graft's endothelium (KP, Khodadoust line, edema); an emergency treated with intensive steroids." },
  "descémétocèle": { term: "descemetocele", def: "Ulcer so deep that only the bulging Descemet membrane holds in the eye's contents: perforation is imminent." },
  "néovascularisation": { term: "neovascularization", def: "Growth of new abnormal vessels (cornea, iris, angle, retina) in response to chronic injury or ischemia." },
  "Seidel": { term: "Seidel", def: "Test with concentrated fluorescein (dark orange under cobalt blue): leaking aqueous dilutes it into a bright green stream; indicates a leak (wound, perforation, leaking bleb)." },
  "RSVP": { term: "RSVP", def: "Redness, Sensitivity to light, Vision ↓, Pain: symptoms a corneal graft patient must report to be seen the same day." },
  "TBUT": { term: "TBUT", def: "Tear breakup time: seconds between a blink and the first dry spot with fluorescein; abnormal if < 10 s." },
  "NIBUT": { term: "NIBUT", def: "Tear breakup time measured without fluorescein by a device; < 10 s is a sign of dry eye (TFOS DEWS III)." },
  "vert de lissamine": { term: "lissamine green", def: "Dye that stains damaged conjunctival and corneal cells or those poorly protected by mucus; read under white light." },
  "Schirmer": { term: "Schirmer", def: "Paper strip at the lid margin for 5 minutes; < 5 mm without anesthesia = severe aqueous deficiency." },
  "MGD": { term: "MGD", def: "Meibomian gland dysfunction: the meibum thickens or no longer flows, and tears evaporate too quickly." },
  "Demodex": { term: "Demodex", def: "Tiny mite of the lashes and glands; in excess, it causes blepharitis with cylindrical sleeves at the base of the lashes." },
  "kératite neurotrophique": { term: "neurotrophic keratitis", def: "Cornea that has lost its sensation (herpes, zoster, diabetes, surgery): the epithelium heals poorly, hence persistent defects and ulcers that are often painless." },
  "agent de conservation": { term: "preservative", def: "Product (often benzalkonium chloride) that prevents contamination of multidose bottles; damages the surface with frequent use." },
  "kératocône": { term: "keratoconus", def: "Disease in which the cornea thins and bulges into a cone, mainly in adolescents and young adults; irregular astigmatism, stabilized by CXL." },
  "ectasie": { term: "ectasia", def: "Cornea that thins and deforms forward; general term (keratoconus, pellucid marginal degeneration, post-LASIK ectasia)." },
  "dégénérescence marginale pellucide": { term: "pellucid marginal degeneration", def: "Ectasia with an inferior band of thinning 1–2 mm above the limbus; \"crab-claw\" topography with against-the-rule astigmatism." },
  "hydrops": { term: "hydrops", def: "Tear in Descemet in advanced keratoconus: water suddenly floods the stroma, which turns white and thick." },
  "anneau de Fleischer": { term: "Fleischer ring", def: "Brown ring of iron in the epithelium around the base of the cone; best seen under cobalt blue light." },
  "stries de Vogt": { term: "Vogt striae", def: "Fine vertical lines in the posterior stroma in keratoconus, which disappear with gentle pressure on the globe." },
  "CXL": { term: "CXL", def: "Corneal cross-linking: riboflavin + ultraviolet A stiffen the cornea to halt progression of keratoconus." },
  "tomographie": { term: "tomography", def: "Imaging that measures both corneal surfaces and thickness everywhere (Scheimpflug, OCT); detects ectasia earlier than topography." },
  "Pentacam": { term: "Pentacam", def: "Widely used Scheimpflug tomographer: curvature, anterior and posterior elevation and thickness maps; the basis of keratoconus follow-up." },
  "pachymétrie": { term: "pachymetry", def: "Measurement of corneal thickness (≈ 540–550 µm centrally); used for edema, ectasia and interpreting IOP." },
  "microscopie spéculaire": { term: "specular microscopy", def: "Photo of the endothelium that counts cells (cells/mm²) and analyzes their size and shape; guttae appear dark." },
  "AS-OCT": { term: "AS-OCT", def: "Anterior segment OCT: non-contact cross-section of the cornea, angle and grafts (depth of an opacity, attachment of a DMEK)." },
  "UBM": { term: "UBM", def: "Ultrasound biomicroscopy: very high-frequency ultrasound of the anterior segment; sees behind the iris, superior for plateau iris." },
  "hystérésis cornéenne": { term: "corneal hysteresis", def: "The cornea's ability to dampen a deformation; when low, it is associated with an increased risk of glaucoma progression." },
  "kératopathie bulleuse": { term: "bullous keratopathy", def: "Chronic corneal edema with painful epithelial bullae when the endothelium no longer pumps (advanced Fuchs, after cataract surgery)." },
  "EBMD": { term: "EBMD", def: "Epithelial basement membrane dystrophy: maps, dots and fingerprints in the epithelium; a common cause of recurrent erosion." },
  "PTK": { term: "PTK", def: "Phototherapeutic keratectomy: the excimer laser smooths or removes the corneal surface (recurrent erosion, superficial opacities)." },
  "pinguécula": { term: "pinguecula", def: "Small yellowish elevation of the conjunctiva near the limbus, sun-related, that does not invade the cornea." },
  "OSSN": { term: "OSSN", def: "Ocular surface squamous neoplasia: gelatinous or white limbal lesion, from dysplasia to carcinoma." },
  "PUK": { term: "PUK", def: "Peripheral ulcerative keratitis: crescent-shaped ulcer and thinning near the limbus, often due to systemic disease (rheumatoid arthritis, vasculitis)." },
  "déficit en cellules souches limbiques": { term: "limbal stem cell deficiency", def: "Loss of the limbal stem cells (burn, contact lenses, surgeries): the conjunctiva covers the cornea, which stays opaque and unstable." },
  "ischémie limbique": { term: "limbal ischemia", def: "Blanching of the limbal vessels after a chemical burn; the more extensive it is, the worse the prognosis." },
  "gouttes fortifiées": { term: "fortified drops", def: "Highly concentrated antibiotics (vancomycin 25 mg/mL, tobramycin 14 mg/mL) compounded by the hospital pharmacy for severe bacterial keratitis." },
  "cycloplégique": { term: "cycloplegic", def: "Drop that dilates the pupil and paralyzes accommodation (cyclopentolate, atropine); relieves ciliary spasm and prevents synechiae." },
  "lentille pansement": { term: "bandage contact lens", def: "Plano soft contact lens that protects a fragile epithelium and reduces pain; always with an antibiotic and follow-up." },
  "membrane amniotique": { term: "amniotic membrane", def: "Inner layer of the placenta, processed and placed on the eye as an anti-inflammatory biological dressing that helps the epithelium heal." },
  "colle cyanoacrylate": { term: "cyanoacrylate glue", def: "Surgical glue that seals a small perforation or extreme corneal thinning; covered with a bandage contact lens." },
  "tarsorraphie": { term: "tarsorrhaphy", def: "Partial closure of the lids (suture, glue or botulinum toxin) to protect an exposed or poorly healing cornea." },
  "cénégermine": { term: "cenegermin", def: "Recombinant human nerve growth factor (Oxervate) drops, for moderate or severe neurotrophic keratitis in adults." },
  "sérum autologue": { term: "autologous serum", def: "Drops prepared from the patient's own blood, rich in growth factors; for severe dry eye or a persistent epithelial defect." },
  "lentille sclérale": { term: "scleral lens", def: "Large rigid lens resting on the sclera, with a fluid reservoir over the cornea: corrects an irregular cornea and protects a diseased surface." },
  "IPL": { term: "IPL", def: "Intense pulsed light: flashes on the eyelid skin that improve refractory meibomian gland dysfunction." },
  "anneaux intracornéens": { term: "intracorneal ring segments", def: "Plastic segments (ICRS) slipped into a stromal tunnel to flatten and regularize a keratoconus; they do not halt progression." },
  "Kmax": { term: "Kmax", def: "Maximum corneal curvature (in diopters) on topography; an increase is one of the signs of keratoconus progression." },
  "règle 1-2-3": { term: "1-2-3 rule", def: "Anterior chamber reaction ≥ 1+, infiltrate ≥ 2 mm or ≤ 3 mm from the center: a single criterion is enough to scrape, culture and give fortified drops." },
  "Acanthamoeba": { term: "Acanthamoeba", def: "Freshwater ameba (tap, pool, lake); in contact lens wearers, a very painful keratitis that resists antibiotics; its cysts are hard to kill." },
  "périnévrite radiaire": { term: "radial perineuritis", def: "Fine infiltrates along the corneal nerves, from the limbus toward the center (radial keratoneuritis); highly suggestive of early Acanthamoeba keratitis." },
});
Object.assign(G.OPH_EN.glossary, {
  "bulbes terminaux": { term: "terminal bulbs", def: "Swellings at the ends of a dendrite's branches: the signature of herpes simplex; absent from pseudodendrites (zoster, Acanthamoeba)." },
  "ulcère géographique": { term: "geographic ulcer", def: "Herpetic dendrite enlarged into an ulcer with scalloped edges, often after a steroid given without an antiviral." },
  "endothéliite": { term: "endotheliitis", def: "Inflammation of the endothelium, often herpetic: localized (disciform) corneal edema with keratic precipitates; steroid under antiviral cover." },
  "signe de Hutchinson": { term: "Hutchinson sign", def: "Zoster vesicles on the tip, side or root of the nose: involvement of the nasociliary nerve, which also supplies the eye; high risk of ocular involvement." },
  "HEDS": { term: "HEDS", def: "Herpetic Eye Disease Study: acyclovir 400 mg BID for 1 year ≈ 45% fewer recurrences of ocular herpes; steroid + antiviral for stromal keratitis." },
  "ZEDS": { term: "ZEDS", def: "Zoster Eye Disease Study (2025): valacyclovir 1 g daily for 1 year after herpes zoster ophthalmicus; less eye disease at 18 months." },
  "SCUT": { term: "SCUT", def: "Steroids for Corneal Ulcers Trial (2012): steroid added after 48 h of antibiotic, with no overall benefit in bacterial keratitis; avoid with Nocardia." },
  "MUTT": { term: "MUTT", def: "Mycotic Ulcer Treatment Trials: natamycin 5% superior to voriconazole 1% (especially Fusarium); added oral voriconazole without benefit." },
  "PK": { term: "PK", def: "Penetrating keratoplasty: sutured full-thickness corneal graft; highest risk of rejection." },
  "DALK": { term: "DALK", def: "Deep anterior lamellar keratoplasty: replaces epithelium and stroma while keeping the patient's Descemet and endothelium; no endothelial rejection." },
  "DSAEK": { term: "DSAEK", def: "Endothelial keratoplasty: donor endothelium, Descemet and a thin layer of posterior stroma, pressed in place by an air bubble; easier to handle than DMEK." },
  "DMEK": { term: "DMEK", def: "Endothelial keratoplasty of Descemet and endothelium only, pressed in place by an air or gas bubble; better vision, less rejection." },
  "neuropathie optique glaucomateuse": { term: "glaucomatous optic neuropathy", def: "Progressive loss of ganglion cells and their axons: an enlarging cup and a matching visual field defect." },
  "GPAO": { term: "POAG", def: "Primary open-angle glaucoma: progressive optic neuropathy, open and normal-looking angle, no other cause; the most common form." },
  "GPN": { term: "NTG", def: "Normal-tension glaucoma: open-angle glaucoma whose IOP stays ≤ 21 mmHg; vascular factors play a larger role." },
  "HTO": { term: "OHT", def: "Ocular hypertension: IOP > 21 mmHg with normal nerve, RNFL and visual field; a risk factor, not yet glaucoma." },
  "suspect de glaucome": { term: "glaucoma suspect", def: "Patient with a suspicious finding (disc, RNFL, field, IOP or angle) without demonstrated glaucomatous neuropathy." },
  "excavation": { term: "cupping", def: "Central hollow of the optic disc, devoid of nerve fibers; it enlarges as fibers die." },
  "C/D": { term: "C/D", def: "Cup-to-disc ratio, mainly vertical; > 0.6 or an asymmetry ≥ 0.2 between eyes is suspicious, depending on disc size." },
  "bord neurorétinien": { term: "neuroretinal rim", def: "Pink tissue between the cup and the disc margin: the remaining nerve fibers; normally thickest inferiorly and superiorly (ISNT)." },
  "encoche": { term: "notch", def: "Focal loss of the neuroretinal rim, often at the inferotemporal pole; a sign highly suggestive of glaucoma." },
  "hémorragie papillaire": { term: "disc hemorrhage", def: "Small flame-shaped hemorrhage at the disc margin (Drance); a sign of activity and a risk factor for progression." },
  "APP": { term: "PPA", def: "Peripapillary atrophy: pale crescent around the disc; the beta zone (visible sclera) is associated with glaucoma and its progression." },
  "PIO cible": { term: "target IOP", def: "IOP chosen for a patient, below which progression is hoped to stop; starting point ≈ 20–30% below baseline IOP, revised as needed." },
  "RNFL": { term: "RNFL", def: "Retinal nerve fiber layer; its thickness around the disc, measured by OCT, decreases in glaucoma." },
  "GCIPL": { term: "GCIPL", def: "Ganglion cell–inner plexiform layer, measured at the macula by OCT; detects central damage, useful at the advanced stage." },
  "red disease": { term: "red disease", def: "OCT false positive: a red result without disease (high myopia, tilted or small disc, segmentation error)." },
  "green disease": { term: "green disease", def: "OCT false negative: a green result despite damage (early glaucoma, edema, epiretinal membrane)." },
  "effet plancher": { term: "floor effect", def: "At the advanced stage, the RNFL no longer falls below ≈ 50–60 µm: OCT no longer tracks progression, and the visual field and GCIPL take over." },
  "structure-fonction": { term: "structure-function", def: "Expected agreement between fiber loss (disc, OCT) and the field defect; inferior nerve damage gives a superior defect." },
  "MD": { term: "MD", def: "Mean deviation of the visual field: overall loss in dB relative to age-matched normals; used for staging." },
  "PSD": { term: "PSD", def: "Pattern standard deviation: indicates whether field loss is localized rather than diffuse; elevated in glaucoma." },
  "VFI": { term: "VFI", def: "Visual field index: percentage of remaining visual function (100% = normal), weighted toward the center; handy for following the trend." },
  "ressaut nasal": { term: "nasal step", def: "Visual field defect that stops sharply at the horizontal meridian, on the nasal side; typical of glaucoma." },
  "champs visuels groupés": { term: "clustered visual fields", def: "Several visual fields close together at baseline (≈ 3 per year for 2 years) to detect a fast progressor early (AAO 2026)." },
  "gonioscopie": { term: "gonioscopy", def: "Examination of the iridocorneal angle with a mirrored lens; tells whether the angle is open or closed and shows synechiae, new vessels, pigment." },
  "indentation": { term: "indentation gonioscopy", def: "Gentle pressure of the gonioscopy lens (4-mirror) that opens a merely appositional angle; synechiae (PAS) stay stuck." },
  "Shaffer": { term: "Shaffer", def: "Grading of angle width from 0 (closed) to 4 (wide, ciliary body band visible) according to the most posterior visible structure." },
  "Van Herick": { term: "Van Herick", def: "Slit-lamp estimate of peripheral anterior chamber depth relative to corneal thickness; grade ≤ 2 → gonioscopy." },
  "trabéculum": { term: "trabecular meshwork", def: "Spongy filter of the angle through which most aqueous humor passes toward Schlemm canal." },
  "canal de Schlemm": { term: "Schlemm canal", def: "Circular canal behind the trabecular meshwork that collects aqueous and delivers it to the episcleral veins; the target of MIGS." },
  "voie uvéosclérale": { term: "uveoscleral outflow", def: "Secondary aqueous outflow through the ciliary muscle (5–30% of outflow); increased by prostaglandins." },
  "éperon scléral": { term: "scleral spur", def: "White landmark of the angle just behind the trabecular meshwork; seeing it means the meshwork is uncovered." },
  "ligne de Schwalbe": { term: "Schwalbe line", def: "End of Descemet membrane: the most anterior landmark of the angle, the front boundary of the trabecular meshwork." },
  "contact iridotrabéculaire": { term: "iridotrabecular contact", def: "Iris pressed against the trabecular meshwork; ≥ 180° on gonioscopy defines angle closure." },
  "PAS": { term: "PAS", def: "Peripheral anterior synechiae: permanent adhesions of the iris to the trabecular meshwork, which do not open on indentation." },
  "synéchies antérieures périphériques": { term: "peripheral anterior synechiae", def: "Permanent adhesions of the iris to the angle (PAS) after angle closure, inflammation or new vessels; they block drainage." },
  "PACS": { term: "PACS", def: "Primary angle-closure suspect: iridotrabecular contact ≥ 180°, normal IOP, no PAS and no neuropathy." },
  "PAC": { term: "PAC", def: "Primary angle closure: iridotrabecular contact with PAS or elevated IOP, without optic neuropathy." },
  "PACG": { term: "PACG", def: "Primary angle-closure glaucoma: angle closure (PAC) with glaucomatous optic neuropathy." },
  "bloc pupillaire": { term: "pupillary block", def: "Aqueous passes poorly between iris and lens; it accumulates behind the iris, which bows forward and closes the angle." },
  "iris plateau": { term: "plateau iris", def: "Anteriorly positioned ciliary body that pushes the iris root into the angle; the angle stays closed despite a patent iridotomy." },
  "glaukomflecken": { term: "glaukomflecken", def: "Small white opacities under the anterior lens capsule, scars of an acute angle-closure attack." },
  "pseudo-exfoliation": { term: "pseudoexfoliation", def: "Age-related disease that deposits flaky white material on the lens, pupil and trabecular meshwork; weak zonules, more aggressive glaucoma." },
  "PXF": { term: "PXF", def: "Abbreviation for pseudoexfoliation (syndrome or pseudoexfoliation glaucoma)." },
  "ligne de Sampaolesi": { term: "Sampaolesi line", def: "Wavy line of pigment anterior to Schwalbe line, seen on gonioscopy; classic in pseudoexfoliation." },
  "dispersion pigmentaire": { term: "pigment dispersion", def: "The concave peripheral iris rubs on the zonules and releases its pigment, which clogs the trabecular meshwork; often a young myopic adult." },
  "fuseau de Krukenberg": { term: "Krukenberg spindle", def: "Vertical band of pigment on the central corneal endothelium, a sign of pigment dispersion." },
  "rubéose": { term: "rubeosis", def: "New vessels on the surface of the iris (rubeosis iridis), first at the pupillary margin, due to an ischemic retina (diabetes, vein occlusion)." },
  "NVA": { term: "NVA", def: "Neovascularization of the angle: vessels crossing the scleral spur toward the trabecular meshwork, which then close the angle with synechiae." },
  "anti-VEGF": { term: "anti-VEGF", def: "Drugs injected into the vitreous (bevacizumab, ranibizumab, aflibercept) that block VEGF, the vessel growth signal; they make new vessels regress quickly." },
  "PRP": { term: "PRP", def: "Panretinal photocoagulation: laser to the ischemic peripheral retina that durably reduces VEGF; the mainstay treatment of rubeosis." },
  "mal-direction": { term: "aqueous misdirection", def: "Malignant glaucoma: aqueous flows into the vitreous instead of the anterior chamber; flat chamber and high IOP after surgery; miotics contraindicated." },
  "SLT": { term: "SLT", def: "Selective laser trabeculoplasty: in-clinic laser to the pigmented trabecular meshwork that improves outflow; a first-line option in POAG." },
  "trabéculoplastie sélective au laser": { term: "selective laser trabeculoplasty", def: "Laser (SLT) that targets the pigmented cells of the trabecular meshwork to increase aqueous outflow; incisionless and repeatable." },
});
Object.assign(G.OPH_EN.glossary, {
  "LPI": { term: "LPI", def: "Laser peripheral iridotomy: a small hole in the iris that relieves pupillary block and lets the angle open." },
  "iridotomie": { term: "iridotomy", def: "Laser opening in the peripheral iris (LPI) to equalize pressure on either side of the iris." },
  "iridoplastie": { term: "iridoplasty", def: "Laser burns on the peripheral iris that contract it and pull it away from the angle; mainly for plateau iris." },
  "MIGS": { term: "MIGS", def: "Minimally invasive glaucoma surgery, done from inside the eye, often with cataract surgery: safe, modest effect." },
  "iStent": { term: "iStent", def: "Titanium micro-implant placed through the trabecular meshwork into Schlemm canal (MIGS), often during cataract surgery." },
  "Hydrus": { term: "Hydrus", def: "Micro-scaffold placed in Schlemm canal over about 90°; it dilates the canal and bypasses the trabecular meshwork (MIGS)." },
  "goniotomie": { term: "goniotomy", def: "Incision or removal of a strip of trabecular meshwork from inside the eye (e.g. KDB blade) to open access to Schlemm canal." },
  "KDB": { term: "KDB", def: "Kahook Dual Blade: double-edged blade that removes a strip of trabecular meshwork (goniotomy) from inside the eye." },
  "GATT": { term: "GATT", def: "Gonioscopy-assisted transluminal trabeculotomy: a suture threaded through all of Schlemm canal and then pulled opens the meshwork over 360°; hyphema is common." },
  "OMNI": { term: "OMNI", def: "System that dilates Schlemm canal (viscocanaloplasty) and then opens the trabecular meshwork (trabeculotomy), from inside the eye." },
  "trabéculectomie": { term: "trabeculectomy", def: "The reference filtering surgery: a scleral trapdoor lets aqueous out under the conjunctiva, where it forms a filtering bleb." },
  "mitomycine C": { term: "mitomycin C", def: "Antimetabolite applied during filtering surgery to keep scarring from closing the bleb; weakens the conjunctiva (leak, infection)." },
  "bulle filtrante": { term: "filtering bleb", def: "Reservoir of aqueous under the conjunctiva created by a trabeculectomy, PreserFlo or XEN; must stay patent and leak-free." },
  "needling": { term: "needling", def: "Needle passed under the conjunctiva (± antimetabolite) to break up fibrosis that is closing a filtering bleb." },
  "PreserFlo": { term: "PreserFlo", def: "MicroShunt: a small polymer tube implanted from outside, from the anterior chamber to the subconjunctival space, with mitomycin C; creates a filtering bleb." },
  "XEN": { term: "XEN", def: "Very thin gelatin tube that drains aqueous under the conjunctiva (filtering bleb), implanted from inside the eye or through an open conjunctival approach." },
  "ripcord": { term: "ripcord", def: "Suture placed in the lumen of a tube (PreserFlo, XEN, Baerveldt) to limit early flow; removed later in clinic if IOP rises." },
  "Ahmed": { term: "Ahmed", def: "Valved drainage tube that limits flow from the time of surgery; less early hypotony, a hypertensive phase is common." },
  "Baerveldt": { term: "Baerveldt", def: "Non-valved drainage tube with a large plate; ligated at first to avoid hypotony, it gives lower IOPs in the long term." },
  "cyclophotocoagulation": { term: "cyclophotocoagulation", def: "Laser that destroys part of the ciliary body to reduce aqueous production; for refractory glaucoma or eyes with low visual potential." },
  "hypotonie": { term: "hypotony", def: "IOP too low, mainly after filtering surgery: risk of flat chamber, macular folds (maculopathy) and choroidal effusion." },
  "blébite": { term: "blebitis", def: "Infection of the filtering bleb (white bleb, red eye) that can progress to endophthalmitis; an emergency, even years after surgery." },
  "lyse de sutures": { term: "laser suture lysis", def: "Laser cutting, through the conjunctiva, of a scleral flap suture after trabeculectomy to increase flow to the bleb." },
  "5-FU": { term: "5-FU", def: "5-fluorouracil: antiscarring agent injected under the conjunctiva after filtering surgery or during needling to curb bleb fibrosis." },
  "maculopathie d’hypotonie": { term: "hypotony maculopathy", def: "Choroidal and retinal folds in the macula when IOP stays too low (especially in young myopes): vision drops." },
  "iridectomie": { term: "iridectomy", def: "Surgical removal of a small piece of peripheral iris; done during a trabeculectomy or when a laser iridotomy is impossible or closes." },
  "goniosynéchialyse": { term: "goniosynechialysis", def: "Surgical separation of peripheral anterior synechiae (PAS) in the angle, often combined with lens extraction." },
  "phtisie": { term: "phthisis", def: "An eye that atrophies and shrinks after a prolonged drop in aqueous production (e.g. excessive cyclophotocoagulation, a very diseased eye)." },
  "PIO": { term: "IOP", def: "Intraocular pressure: normal 10–21 mmHg, mean ≈ 15–16; the main risk factor for glaucoma and the only proven modifiable one." },
  "OCT": { term: "OCT", def: "Optical coherence tomography: non-contact cross-sectional imaging; measures the RNFL around the disc and the ganglion cells at the macula." },
  "TSNIT": { term: "TSNIT", def: "Reading order of the OCT RNFL curve: Temporal, Superior, Nasal, Inferior, Temporal; normally two humps (superior and inferior)." },
  "ISNT": { term: "ISNT", def: "Rule for the normal neuroretinal rim, thickest Inferiorly, then Superiorly, Nasally and Temporally; useful but imperfect." },
  "24-2": { term: "24-2", def: "Humphrey visual field program: 54 points spaced 6° apart in the central 24°; the baseline glaucoma test." },
  "10-2": { term: "10-2", def: "Humphrey visual field program with a dense grid over the central 10°; reveals paracentral defects the 24-2 can miss." },
  "Esterman": { term: "Esterman", def: "Screening visual field done with both eyes open (binocular); used to check SAAQ driving standards." },
  "Tono-Pen": { term: "Tono-Pen", def: "Handheld electronic tonometer; useful if the cornea is irregular or edematous, or if the patient cannot sit at the slit lamp." },
  "PGA": { term: "PGA", def: "Prostaglandin analogs (latanoprost, travoprost, bimatoprost): evening drop that increases uveoscleral outflow; the usual first drop." },
  "IAC": { term: "CAI", def: "Carbonic anhydrase inhibitor: reduces aqueous production; as drops (dorzolamide, brinzolamide) or oral or IV (acetazolamide); these are sulfonamides." },
  "OHTS": { term: "OHTS", def: "Ocular Hypertension Treatment Study: in OHT patients at 24–32 mmHg, lowering IOP by about 20% reduced 5-year conversion to glaucoma from 9.5% to 4.4%." },
  "EMGT": { term: "EMGT", def: "Early Manifest Glaucoma Trial: treating early glaucoma reduces progression (45% vs 62%); each mmHg of lowering ≈ 10% less risk." },
  "LiGHT": { term: "LiGHT", def: "Laser in Glaucoma and Ocular Hypertension Trial: first-line SLT vs drops; at 6 years, 69.8% of SLT eyes at target without further treatment and less progression." },
  "CNTGS": { term: "CNTGS", def: "Collaborative Normal-Tension Glaucoma Study: in NTG, lowering IOP by 30% reduces progression (≈ 12% vs 35%), but many untreated patients remain stable." },
  "LoGTS": { term: "LoGTS", def: "Low-Pressure Glaucoma Treatment Study: in NTG, less field progression on brimonidine than on timolol, with many dropouts (allergy)." },
  "EAGLE": { term: "EAGLE", def: "Trial (Lancet 2016): in patients ≥ 50 with PAC and IOP ≥ 30 mmHg or PACG, clear lens extraction controls IOP better than laser iridotomy." },
  "ZAP": { term: "ZAP", def: "Zhongshan Angle Closure Prevention Trial (Lancet 2019): in PACS, prophylactic iridotomy roughly halves the risk, but that risk is very low." },
  "effusion ciliochoroïdienne": { term: "ciliochoroidal effusion", def: "Fluid around the ciliary body and choroid (e.g. topiramate): iris and lens rotate forward and close the angle on both sides, with acute myopia." },
  "phacodonésis": { term: "phacodonesis", def: "Trembling of the lens with eye movements: a sign of weak zonules (pseudoexfoliation, trauma); high-risk cataract surgery." },
  "anneau de tension capsulaire": { term: "capsular tension ring", def: "Flexible ring placed in the lens capsular bag during cataract surgery to support weak zonules (pseudoexfoliation)." },
  "UGH": { term: "UGH", def: "Uveitis-glaucoma-hyphema syndrome: a malpositioned intraocular lens rubs the iris or ciliary body." },
  "VEGF": { term: "VEGF", def: "Vascular endothelial growth factor: a signal secreted by an ischemic retina that makes new vessels grow." },
  "OVCR": { term: "CRVO", def: "Central retinal vein occlusion; the ischemic form predisposes to neovascular glaucoma, especially in the first 3 months." },
  "NVI": { term: "NVI", def: "Neovascularization of the iris (rubeosis), first at the pupillary margin; look for it before dilating the pupil." },
  "répondeur": { term: "steroid responder", def: "Person whose IOP rises on corticosteroids; more common in children, with POAG or with high myopia." },
  "iris bombé": { term: "iris bombé", def: "Iris stuck to the lens around the whole pupil (posterior synechiae): aqueous accumulates behind it, the iris bows forward and closes the angle; an emergency." },
  "trabéculite": { term: "trabeculitis", def: "Inflammation of the trabecular meshwork itself (herpes, CMV): IOP rises sharply with few cells in the chamber." },
  "CMV": { term: "CMV", def: "Cytomegalovirus, a herpes-group virus: cause of recurrent unilateral hypertensive anterior uveitis (coin-shaped precipitates), often behind Posner-Schlossman; diagnosed by aqueous PCR." },
  "Posner-Schlossman": { term: "Posner-Schlossman", def: "Recurrent attacks in one eye: very high IOP, few cells, a few fine precipitates, open angle (glaucomatocyclitic crisis); often linked to CMV." },
  "sclérose nucléaire": { term: "nuclear sclerosis", def: "Age-related hardening and yellowing of the lens nucleus; the start of nuclear cataract, often with a myopic shift." },
  "seconde vue": { term: "second sight", def: "Return of near vision without glasses in a presbyope, caused by the myopic shift of a nuclear cataract." },
  "LOCS III": { term: "LOCS III", def: "Lens Opacities Classification System III: standardized scale that grades nuclear, cortical and posterior subcapsular cataracts against reference photos." },
  "cataracte sous-capsulaire postérieure": { term: "posterior subcapsular cataract", def: "Granular plaque at the center of the posterior lens surface; linked to steroids, diabetes, radiotherapy; causes glare and difficulty at near." },
  "rétroillumination": { term: "retroillumination", def: "Illumination using the red reflex from the fundus (dilated pupil): lens or corneal opacities stand out against an orange background." },
  "cataracte morgagnienne": { term: "morgagnian cataract", def: "Hypermature cataract: liquefied or resorbed cortex, nucleus sinking to the bottom of the capsular bag." },
  "bleu trypan": { term: "trypan blue", def: "Vital dye that stains the anterior capsule (capsulorhexis without a red reflex) or a DMEK graft to make it easier to see." },
  "opacification capsulaire postérieure": { term: "posterior capsule opacification", def: "Haze of the posterior capsule behind the IOL, months or years after cataract surgery; treated with YAG capsulotomy." },
});
Object.assign(G.OPH_EN.glossary, {
  "perles d’Elschnig": { term: "Elschnig pearls", def: "Small translucent bubbles formed by regrowth of lens cells on the posterior capsule." },
  "capsulotomie YAG": { term: "YAG capsulotomy", def: "Nd:YAG laser opening of an opacified posterior capsule; risks: IOP spike, cystoid macular edema, retinal detachment." },
  "B-scan": { term: "B-scan", def: "Two-dimensional ocular ultrasound: shows vitreous, retina, choroid and masses when the fundus cannot be seen." },
  "nanophtalmie": { term: "nanophthalmos", def: "Very short eye with thick sclera and high hyperopia; risk of angle closure and uveal effusion, especially around surgery." },
  "effusion uvéale": { term: "uveal effusion", def: "Accumulation of fluid under the choroid and ciliary body, spontaneous (nanophthalmos) or surgical; can push the iris and lens forward." },
  "rhegmatogène": { term: "rhegmatogenous", def: "Describes a retinal detachment caused by a retinal tear or hole." },
  "signe de Shafer": { term: "Shafer sign", def: "Pigment granules (tobacco dust) in the anterior vitreous, seen at the slit lamp; strongly associated with a retinal tear." },
  "décollement postérieur du vitré": { term: "posterior vitreous detachment", def: "Age-related separation of the vitreous from the retina; causes flashes and floaters and can cause a tear." },
  "décollement choroïdien": { term: "choroidal detachment", def: "Elevation of the choroid by fluid (serous) or blood (hemorrhagic) between choroid and sclera; smooth brown domes in the periphery." },
  "hémorragie suprachoroïdienne": { term: "suprachoroidal hemorrhage", def: "Bleeding between choroid and sclera, often during or after surgery: sudden pain, high IOP, flat chamber." },
  "signe du T": { term: "T sign", def: "On B-scan, fluid under Tenon capsule around the optic nerve outlining a T: a sign of posterior scleritis." },
  "DMLA": { term: "AMD", def: "Age-related macular degeneration: dry form (drusen, atrophy) or neovascular form (abnormal vessels under the macula, hemorrhage, fluid)." },
  "drusen": { term: "drusen", def: "Yellow deposits under the retinal pigment epithelium; their size and number define the stages of AMD." },
  "atrophie géographique": { term: "geographic atrophy", def: "Advanced form of dry AMD: a sharply demarcated area of pigment epithelium atrophy through which choroidal vessels are visible." },
  "grille d’Amsler": { term: "Amsler grid", def: "Grid viewed one eye at a time to detect distorted lines or a missing central area (macular disease)." },
  "microanévrismes": { term: "microaneurysms", def: "Small dilations of retinal capillaries seen as red dots; the first sign of diabetic retinopathy." },
  "veines en chapelet": { term: "venous beading", def: "Retinal veins of irregular caliber, like rosary beads; a sign of ischemia in severe diabetic retinopathy." },
  "IRMA": { term: "IRMA", def: "Intraretinal microvascular abnormalities: small tortuous vessels within the retina, a sign of severe nonproliferative retinopathy." },
  "règle 4-2-1": { term: "4-2-1 rule", def: "Severe nonproliferative retinopathy if one criterion: numerous hemorrhages in all 4 quadrants, venous beading in 2 quadrants or definite IRMA in 1." },
  "NVD": { term: "NVD", def: "Neovascularization of the disc: a sign of ischemic proliferative retinopathy." },
  "NVE": { term: "NVE", def: "Neovascularization elsewhere on the retina, often along the vascular arcades." },
  "œdème maculaire diabétique": { term: "diabetic macular edema", def: "Thickening of the macula from capillary leakage in a diabetic; intraretinal cysts on OCT; treated mainly with anti-VEGF if center-involving." },
  "tache rouge cerise": { term: "cherry-red spot", def: "Center of the macula that stays red in a central artery occlusion: the fovea, which has no inner retina, lets the choroid show through while the surrounding retina whitens." },
  "OACR": { term: "CRAO", def: "Central retinal artery occlusion: abrupt loss of blood flow to the retina, painless vision loss; the equivalent of a stroke, immediate transfer to the ED." },
  "OBAR": { term: "BRAO", def: "Branch retinal artery occlusion, often from an embolus; loss of one sector of the visual field; immediate stroke workup in the ED." },
  "OBVR": { term: "BRVO", def: "Branch retinal vein occlusion, at an arteriovenous crossing; fan-shaped hemorrhages confined to one sector." },
  "plaque de Hollenhorst": { term: "Hollenhorst plaque", def: "Bright yellow cholesterol embolus lodged in a retinal arteriole, most often from a carotid plaque; a vascular warning sign." },
  "artérite à cellules géantes": { term: "giant cell arteritis", def: "Large-vessel vasculitis after age 50 (temporal arteritis): headache, jaw claudication; can blind both eyes; urgent steroids." },
  "artère ciliorétinienne": { term: "cilioretinal artery", def: "Inconstant artery from the choroidal circulation that supplies the retina between the disc and the macula; it can spare central vision in a CRAO." },
  "glaucome des 90 jours": { term: "90-day glaucoma", def: "Nickname for neovascular glaucoma that typically occurs within the first three months after an ischemic CRVO (also called \"100-day glaucoma\")." },
  "nodules cotonneux": { term: "cotton-wool spots", def: "Small fluffy white retinal patches: infarcts of the nerve fiber layer (hypertension, diabetes, occlusions, HIV)." },
  "croisement artérioveineux pathologique": { term: "AV nicking", def: "Sign of chronic hypertension: the vein looks pinched or interrupted where the thickened arteriole crosses it." },
  "hypertension maligne": { term: "malignant hypertension", def: "Very severe hypertension with organ damage; on fundus exam, swollen disc, hemorrhages and cotton-wool spots. A medical emergency." },
  "membrane épirétinienne": { term: "epiretinal membrane", def: "Thin fibrous film on the surface of the macula that wrinkles it: blurred, distorted vision; seen on OCT, operated if bothersome." },
  "trou maculaire": { term: "macular hole", def: "Opening in the fovea: full-thickness (all layers, surgery) or lamellar (partial, often monitored). Diagnosed on OCT." },
  "CRSC": { term: "CSCR", def: "Central serous chorioretinopathy: clear fluid under the macula, promoted by stress and corticosteroids by any route; often resolves on its own." },
  "métamorphopsies": { term: "metamorphopsia", def: "Distortion of images: straight lines look wavy. A sign of macular disease (membrane, hole, fluid)." },
  "DPV": { term: "PVD", def: "Posterior vitreous detachment: the vitreous gel separates from the retina with age; flashes and floaters; can tear the retina." },
  "anneau de Weiss": { term: "Weiss ring", def: "Floating ring in front of the disc: vitreous detached from around the optic nerve, proof of a posterior vitreous detachment." },
  "dégénérescence palissadique": { term: "lattice degeneration", def: "Areas of thinned peripheral retina, with white lines and pigment; predispose to holes and retinal detachment, especially in myopes." },
  "rétinoschisis": { term: "retinoschisis", def: "Splitting of the retina into two layers, a smooth, immobile dome, often benign; to be distinguished from a retinal detachment." },
  "hyalose astéroïde": { term: "asteroid hyalosis", def: "Small bright particles of calcium and lipids suspended in the vitreous; benign, normal vision, but sometimes interfere with fundus imaging." },
  "vitrite": { term: "vitritis", def: "Inflammation of the vitreous: cells that haze the fundus view, as in posterior uveitis or infection." },
  "synéchies postérieures": { term: "posterior synechiae", def: "Adhesions between iris and lens after uveitis; irregular pupil; over 360°, they cause iris bombé." },
  "rétinite à CMV": { term: "CMV retinitis", def: "Retinal infection by cytomegalovirus in immunosuppressed patients: granular white necrosis with hemorrhages; antivirals." },
  "nécrose rétinienne aiguë": { term: "acute retinal necrosis", def: "Viral retinitis (VZV, HSV) with rapid, confluent peripheral necrosis, vasculitis and vitritis; urgent antivirals; high risk of retinal detachment." },
  "endophtalmie": { term: "endophthalmitis", def: "Infection inside the eye (after surgery, from a bleb, trauma or via the blood): pain, hypopyon, vitritis; urgent tap and intravitreal antibiotics." },
  "panophtalmie": { term: "panophthalmitis", def: "Infection of the whole globe spreading to the sclera and orbit: swollen lids, chemosis, proptosis; very poor visual prognosis." },
  "œdème papillaire": { term: "papilledema", def: "Strictly speaking, swelling of the optic discs due to raised intracranial pressure; urgent neuroimaging before the lumbar puncture." },
  "neurorétinite": { term: "neuroretinitis", def: "Inflammation of the optic nerve with a star of exudates at the macula, often due to Bartonella henselae (cat-scratch disease)." },
  "étoile maculaire": { term: "macular star", def: "Lipid exudates arranged in spokes around the fovea (neuroretinitis, severe hypertension)." },
  "anisocorie physiologique": { term: "physiologic anisocoria", def: "Pupils differing in size by at most 1 mm, with a similar difference in dark and light; normal." },
  "syndrome de Horner": { term: "Horner syndrome", def: "Damage to the eye's sympathetic pathway: small pupil, mild ptosis, sometimes loss of sweating; if recent and painful, rule out carotid dissection." },
  "test à l’apraclonidine": { term: "apraclonidine test", def: "One drop of apraclonidine in each eye: in Horner, the small pupil dilates and the anisocoria reverses (denervation hypersensitivity)." },
  "hémianopsie homonyme": { term: "homonymous hemianopia", def: "Loss of the same half of the visual field in both eyes, bounded by the vertical meridian: a lesion behind the chiasm (stroke, tumor)." },
  "nævus choroïdien": { term: "choroidal nevus", def: "Flat, benign pigmented lesion of the choroid; to be photographed and monitored for signs of melanoma." },
  "mélanome choroïdien": { term: "choroidal melanoma", def: "Malignant tumor of the choroid, the most common primary intraocular malignancy in adults; referral to ocular oncology." },
  "pigment orange": { term: "orange pigment", def: "Lipofuscin on the surface of a pigmented choroidal lesion; a risk factor for melanoma." },
  "commotio retinae": { term: "commotio retinae", def: "Whitening of the outer retina after blunt trauma (Berlin edema at the posterior pole), usually transient." },
  "IC3D": { term: "IC3D", def: "International Committee for Classification of Corneal Dystrophies: classifies dystrophies by the layer involved and the gene." },
  "TGFBI": { term: "TGFBI", def: "Gene for a corneal protein (keratoepithelin); its mutations cause Reis-Bücklers, granular and lattice dystrophies; LASIK worsens these deposits." },
  "dystrophie granulaire": { term: "granular dystrophy", def: "Dominant stromal dystrophy (TGFBI): discrete white \"breadcrumb\" opacities with clear stroma between them; hyaline deposits (Masson trichrome)." },
  "dystrophie grillagée": { term: "lattice dystrophy", def: "Stromal dystrophy: branching lines of amyloid in the stroma, frequent recurrent erosions; type 1 linked to the TGFBI gene." },
  "dystrophie maculaire": { term: "macular corneal dystrophy", def: "Recessive stromal dystrophy (CHST6): diffuse haze out to the limbus, ill-defined spots, thin cornea; mucopolysaccharides (Alcian blue)." },
  "dystrophie d’Avellino": { term: "Avellino dystrophy", def: "Granular dystrophy type 2 (TGFBI): snowflake and linear opacities; LASIK markedly worsens the deposits." },
  "dystrophie de Reis-Bücklers": { term: "Reis-Bücklers dystrophy", def: "Dystrophy of Bowman layer (TGFBI): gray reticular opacities, painful erosions from childhood, rapid recurrence after PTK or grafting." },
  "dystrophie polymorphe postérieure": { term: "posterior polymorphous corneal dystrophy", def: "Inherited (dominant), bilateral endothelial dystrophy: vesicles and bands at Descemet; sometimes iris adhesions and glaucoma." },
  "DPP": { term: "PPCD", def: "Posterior polymorphous corneal dystrophy: vesicles or bands at Descemet, inherited, sometimes associated with glaucoma." },
  "CHED": { term: "CHED", def: "Congenital hereditary endothelial dystrophy: cloudy, thickened corneas from birth; to be distinguished from congenital glaucoma." },
  "amyloïde": { term: "amyloid", def: "Misfolded protein forming fibrils; stained by Congo red, with apple-green birefringence under polarized light." },
});
Object.assign(G.OPH_EN.glossary, {
  "kératopathie en bande": { term: "band keratopathy", def: "Calcium deposit in Bowman layer, as a horizontal band between the lids; chronic uveitis, phthisis, silicone oil, hypercalcemia." },
  "EDTA": { term: "EDTA", def: "Chelator (ethylenediaminetetraacetic acid) that binds calcium; applied to the scraped cornea to dissolve band keratopathy." },
  "arc cornéen": { term: "corneal arcus", def: "Gray-white ring of lipid in the peripheral stroma, separated from the limbus by a clear interval; before age 50, lipid panel." },
  "intervalle lucide": { term: "lucid interval", def: "Band of clear cornea between a peripheral deposit (arcus, calcific band) and the limbus." },
  "cornée verticillée": { term: "cornea verticillata", def: "Golden-brown whorl lines in the epithelium; amiodarone, hydroxychloroquine or Fabry disease; rarely affects vision." },
  "kératopathie lipidique": { term: "lipid keratopathy", def: "Yellow lipid deposit in the stroma, leaking from abnormal vessels (after HSV, zoster, trauma); treated by closing the vessels." },
  "imprégnation hématique": { term: "corneal blood staining", def: "Red-brown, then greenish, staining of the stroma by blood from a prolonged hyphema with high IOP; clears slowly from the periphery toward the center." },
  "anneau de Kayser-Fleischer": { term: "Kayser-Fleischer ring", def: "Brown-green or golden ring of copper in peripheral Descemet, first superiorly and inferiorly; a sign of Wilson disease." },
  "anneau de rouille": { term: "rust ring", def: "Brown halo of iron oxide around a ferrous corneal foreign body; forms within hours and is removed with a burr." },
  "kératopathie cristalline infectieuse": { term: "infectious crystalline keratopathy", def: "Stromal infection with branching white crystals and little inflammation, mainly viridans streptococci in a graft on steroids; culture is mandatory." },
  "kératite interstitielle": { term: "interstitial keratitis", def: "Inflammation of the stroma without ulceration, with deep vessels; congenital syphilis, HSV, zoster, tuberculosis; leaves ghost vessels." },
  "vaisseaux fantômes": { term: "ghost vessels", def: "Deep stromal vessels empty of blood, scars of old interstitial keratitis; best seen on retroillumination." },
  "haze": { term: "haze", def: "Subepithelial clouding (fibrosis) after surface refractive surgery or PTK; reduced by mitomycin C." },
  "PKR": { term: "PRK", def: "Photorefractive keratectomy: excimer laser applied to the surface after epithelial removal, without a flap." },
  "LASIK": { term: "LASIK", def: "Laser-assisted in situ keratomileusis: excimer laser applied to the stroma under a corneal flap that is cut and then replaced." },
  "follicules": { term: "follicles", def: "Small pale conjunctival domes made of lymphocyte clusters, with vessels around the base; suggest virus, Chlamydia or drop toxicity." },
  "papilles": { term: "papillae", def: "Polygonal conjunctival elevations with a central vessel; a nonspecific reaction (allergy, contact lenses, blepharitis, bacteria)." },
  "papilles géantes": { term: "giant papillae", def: "Papillae larger than 1 mm, cobblestoned on the upper tarsus: vernal, atopic or giant papillary conjunctivitis (contact lenses, prosthesis, suture)." },
  "ganglion préauriculaire": { term: "preauricular node", def: "Lymph node in front of the ear; palpable and tender in adenoviral, herpetic, chlamydial or gonococcal conjunctivitis." },
  "infiltrats sous-épithéliaux": { term: "subepithelial infiltrates", def: "Small round opacities beneath the epithelium, 1–2 weeks after adenoviral infection; an immune reaction that can blur vision for months." },
  "pseudomembranes": { term: "pseudomembranes", def: "Layer of fibrin and cells stuck to the tarsal conjunctiva that peels off without bleeding; notably in severe adenovirus." },
  "points de Horner-Trantas": { term: "Horner-Trantas dots", def: "Small gelatinous white clusters at the limbus, made of eosinophils and epithelial cells; typical of vernal keratoconjunctivitis." },
  "ulcère en bouclier": { term: "shield ulcer", def: "Oval epithelial defect of the superior cornea in vernal disease, sometimes covered with a plaque of mucus and fibrin; same-day treatment." },
  "KLS": { term: "SLK", def: "Superior limbic keratoconjunctivitis: inflammation of the superior bulbar conjunctiva and limbus, often associated with thyroid disease." },
  "stabilisateur des mastocytes": { term: "mast cell stabilizer", def: "Drop that keeps mast cells from releasing histamine and mediators; preventive effect, often combined with an antihistamine (olopatadine, ketotifen)." },
  "pannus": { term: "pannus", def: "Vessels and fibrous tissue invading the peripheral cornea from the limbus (Chlamydia superiorly, rosacea inferiorly, contact lenses)." },
  "phlyctènes": { term: "phlyctenules", def: "Small white inflammatory nodules at the limbus or on the cornea, a hypersensitivity reaction (staphylococcus, rosacea); often leave a vessel behind." },
  "symblépharon": { term: "symblepharon", def: "Scarring adhesion between the palpebral and bulbar conjunctiva; a complication of severe chronic inflammation and burns." },
  "TAAN": { term: "NAAT", def: "Nucleic acid amplification test (PCR); detects Chlamydia and gonococcus on a conjunctival swab." },
  "ITSS": { term: "STBBI", def: "Sexually transmitted and blood-borne infections (Chlamydia, gonorrhea, syphilis, HIV, hepatitis)." },
  "pinguéculite": { term: "pingueculitis", def: "Inflamed pinguecula: a red, irritated yellowish nodule at the nasal or temporal limbus; tears, ± a short course of topical steroid or NSAID." },
  "kératite marginale": { term: "marginal keratitis", def: "Sterile infiltrates of the peripheral cornea separated from the limbus by a clear interval; a reaction to staphylococcal antigens from the lid margin." },
  "intervalle clair": { term: "clear interval", def: "Band of transparent cornea between a peripheral lesion and the limbus; present in marginal keratitis and arcus senilis, absent in PUK." },
  "ulcère de Mooren": { term: "Mooren ulcer", def: "Very painful peripheral ulcer with an overhanging edge, without systemic disease; a diagnosis of exclusion after a complete workup." },
  "Terrien": { term: "Terrien degeneration", def: "Terrien marginal degeneration: slow, painless peripheral thinning, often superior, with a lipid line and against-the-rule astigmatism." },
  "dellen": { term: "dellen", def: "Small dish of corneal thinning from drying, next to an elevated lesion that prevents tears from spreading; reversible with lubrication." },
  "test à la phényléphrine": { term: "phenylephrine test", def: "A drop of phenylephrine 2.5% blanches the superficial episcleral vessels (episcleritis) but not the deep plexus (scleritis)." },
  "épisclérite": { term: "episcleritis", def: "Benign inflammation of the tissue beneath the conjunctiva: mildly painful sectoral redness that blanches with phenylephrine; often idiopathic and self-limited." },
  "sclérite": { term: "scleritis", def: "Inflammation of the sclera, painful (wakes the patient at night), violaceous hue, often linked to systemic disease; diffuse, nodular, necrotizing and posterior forms." },
  "scléromalacie perforante": { term: "scleromalacia perforans", def: "Necrotizing scleritis without inflammation, mainly in long-standing rheumatoid arthritis: bluish patches of thinned sclera through which the uvea shows." },
  "sclérite postérieure": { term: "posterior scleritis", def: "Scleritis behind the equator: pain, little redness, choroidal folds, exudative detachment; B-scan with a T sign." },
  "complexes immuns": { term: "immune complexes", def: "Antibodies bound to their antigen that deposit in small vessels, activate complement and attract neutrophils (vasculitis)." },
  "collagénases": { term: "collagenases", def: "Enzymes (metalloproteinases) that cut collagen; released by neutrophils and keratocytes, they melt the stroma." },
  "GPA": { term: "GPA", def: "Granulomatosis with polyangiitis (formerly Wegener disease): ANCA vasculitis affecting sinuses, lungs and kidneys; can cause PUK and necrotizing scleritis." },
  "ANCA": { term: "ANCA", def: "Antineutrophil cytoplasmic antibodies; markers of vasculitides such as GPA." },
  "AINS": { term: "NSAIDs", def: "Nonsteroidal anti-inflammatory drugs (ibuprofen, naproxen; ketorolac drops): block cyclooxygenase; as drops, avoid on a thinning cornea." },
  "mégalopapille": { term: "megalopapilla", def: "Congenitally very large optic disc, with a large physiologic cup and a normal rim; mimics glaucoma but can also coexist with true glaucoma." },
  "papille inclinée": { term: "tilted disc", def: "Disc that enters the globe obliquely, common in myopes: oval appearance, crescent of atrophy, OCT and field sometimes falsely abnormal." },
  "hypoplasie du nerf optique": { term: "optic nerve hypoplasia", def: "Congenitally small optic nerve: a small disc with a double ring; when bilateral, it requires an MRI and a pituitary workup (septo-optic dysplasia)." },
  "atrophie optique dominante": { term: "dominant optic atrophy", def: "Autosomal dominant inherited disease (OPA1 gene): bilateral vision loss from childhood, blue-yellow defect, temporal disc pallor." },
  "atrophie en bande": { term: "band atrophy", def: "Horizontal, nasal and temporal pallor of the disc, due to a lesion of the chiasm or optic tract; also called bow-tie atrophy." },
  "drusen papillaires": { term: "optic disc drusen", def: "Calcified deposits in the optic nerve head: lumpy disc, pseudo-edema, slow field defects; visible on B-scan and autofluorescence." },
  "vaisseaux optociliaires": { term: "optociliary shunt vessels", def: "Collaterals between retinal and choroidal veins at the disc, a sign of chronic impairment of venous outflow (optic nerve sheath meningioma, old vein occlusion)." },
  "vaisseau circumlinéaire": { term: "circumlinear vessel", def: "Small vessel running along the edge of the cup; when the rim thins, it is left \"bared\", separated from the edge: a glaucomatous sign." },
  "baïonnette": { term: "bayoneting", def: "Sharp bend of a vessel that dives at the edge of a deep cup and then runs along the floor of the hollow." },
  "DPAR": { term: "RAPD", def: "Relative afferent pupillary defect: the pupils dilate when the light moves from the good eye to the affected eye; a sign of optic nerve damage." },
  "NOIA": { term: "AION", def: "Anterior ischemic optic neuropathy: infarction of the optic nerve head; the arteritic form (giant cell arteritis) is an emergency." },
  "glaucome phacomorphique": { term: "phacomorphic glaucoma", def: "Secondary angle closure from a swollen lens pushing the iris forward; lower IOP, then remove the lens." },
  "glaucome phacolytique": { term: "phacolytic glaucoma", def: "Open-angle glaucoma: proteins from a mature or hypermature cataract leak through the intact capsule and macrophages clog the trabecular meshwork." },
  "syndrome UGH": { term: "UGH syndrome", def: "Uveitis-glaucoma-hyphema: an intraocular lens rubs the iris or ciliary body, causing inflammation, repeated bleeding and IOP spikes." },
  "récession de l’angle": { term: "angle recession", def: "Tear in the ciliary body after blunt trauma: widened ciliary body band on gonioscopy; risk of glaucoma years later." },
  "hyphéma": { term: "hyphema", def: "Blood in the anterior chamber, often after trauma; graded by the height of the level, from microhyphema to grade IV (total)." },
  "imbibition hématique": { term: "hematic imbibition of the cornea", def: "Red-brown staining of the cornea by blood from a hyphema, promoted by high IOP and a fragile endothelium; clears very slowly (same entity as corneal blood staining)." },
  "trait drépanocytaire": { term: "sickle cell trait", def: "Carrier of one hemoglobin S gene; in a hyphema, red cells deform, clog the trabecular meshwork and IOP rises more easily." },
  "glaucome aphaque": { term: "aphakic glaucoma", def: "Glaucoma after congenital cataract surgery, often open-angle, which can appear years later: monitor IOP for life." },
  "cellules fantômes": { term: "ghost cells", def: "Degenerated, rigid, khaki-colored red cells from a vitreous hemorrhage that clog the trabecular meshwork (ghost cell glaucoma)." },
  "uvéite phaco-antigénique": { term: "phacoantigenic uveitis", def: "Granulomatous inflammation against lens proteins after capsular rupture (trauma, surgery)." },
  "C3F8": { term: "C3F8", def: "Perfluoropropane: gas injected into the vitreous that remains for several weeks and expands at altitude or under nitrous oxide." },
  "SF6": { term: "SF6", def: "Sulfur hexafluoride: gas injected into the vitreous, resorbed faster than C3F8; same prohibitions (flying, nitrous oxide)." },
  "cyclodialyse": { term: "cyclodialysis", def: "Detachment of the ciliary body from the scleral spur after trauma: aqueous escapes under the choroid, giving a low IOP that can rise abruptly when the cleft closes." },
});
Object.assign(G.OPH_EN.glossary, {
  "transillumination": { term: "transillumination", def: "Light reflected from the fundus that passes through the iris where its pigment epithelium is missing: defects appear as bright areas." },
  "stries de Haab": { term: "Haab striae", def: "Linear breaks in Descemet, horizontal or concentric to the limbus, caused by stretching of the infant cornea under high IOP; they persist for life." },
  "embryotoxon postérieur": { term: "posterior embryotoxon", def: "Thickened, anteriorly displaced Schwalbe line, visible at the slit lamp as a white line near the limbus; common on its own, it is part of the Axenfeld-Rieger spectrum." },
  "syndrome ICE": { term: "ICE syndrome", def: "Iridocorneal endothelial syndrome: abnormal endothelium, in one eye, that migrates over the angle and iris; corneal edema, synechiae, corectopia, glaucoma. Variants: Chandler, essential iris atrophy, Cogan-Reese." },
  "Axenfeld-Rieger": { term: "Axenfeld-Rieger", def: "Congenital, bilateral, dominant anterior segment anomaly: posterior embryotoxon, iris strands, corectopia, dental or umbilical anomalies; high risk of glaucoma." },
  "Sturge-Weber": { term: "Sturge-Weber", def: "Encephalotrigeminal angiomatosis: facial port-wine stain (V1 territory), meningeal angioma (seizures) and choroidal hemangioma; ipsilateral glaucoma is common." },
  "buphtalmie": { term: "buphthalmos", def: "Enlargement of the whole globe (\"ox eye\") from high IOP before about age 3, while the sclera and cornea are still elastic." },
  "trabéculotomie": { term: "trabeculotomy", def: "External-approach angle surgery: a probe or suture passed into Schlemm canal tears its inner wall and the trabecular meshwork to reopen outflow." },
  "trabéculodysgénésie": { term: "trabeculodysgenesis", def: "Incomplete development of the trabecular meshwork and angle, the cause of primary congenital glaucoma." },
  "corectopie": { term: "corectopia", def: "Pupil displaced from its central position, often distorted (oval)." },
  "polycorie": { term: "polycoria", def: "Several openings in the iris that look like pupils (often iris holes: pseudopolycoria)." },
  "procès iriens": { term: "iris processes", def: "Fine, lacy strands of iris running from the iris root toward the spur or trabecular meshwork; a normal variant that does not hide the angle." },
  "anomalie de Peters": { term: "Peters anomaly", def: "Congenital central corneal opacity from a defect in Descemet and endothelium, with iris or lens adhesions to the cornea; glaucoma is common." },
  "aniridie": { term: "aniridia", def: "Near-absent iris (stump visible on gonioscopy), linked to the PAX6 gene: corneal disease, underdeveloped fovea, nystagmus, glaucoma. Sporadic form: screen for Wilms tumor." },
  "argent martelé": { term: "hammered silver", def: "Finely granular, shiny appearance of the endothelium, like beaten metal, typical of ICE syndrome." },
  "examen sous anesthésie": { term: "examination under anesthesia", def: "Complete exam of a child under general anesthesia: IOP, corneal diameter, gonioscopy, refraction, disc; often followed by surgery in the same session." },
  "amblyopie": { term: "amblyopia", def: "Reduced vision in one eye because the brain did not learn to use it during childhood (blurred or deviated image); treated with glasses and patching." },
  "sulcus": { term: "sulcus", def: "Space between the posterior surface of the iris and the ciliary body, in front of the capsule; an IOL is placed there when the capsular bag cannot hold it." },
  "microhyphéma": { term: "microhyphema", def: "Red blood cells suspended in the anterior chamber, without a visible layered level of blood." },
  "angiome plan": { term: "port-wine stain", def: "Flat red or purple capillary malformation of the skin, present from birth." },
  "capture optique": { term: "optic capture", def: "IOL optic passed behind the capsular opening (rhexis) while the haptics stay in front: stabilizes the IOL and moves it away from the iris." },
  "haptiques": { term: "haptics", def: "Arms of an intraocular lens that keep it centered in the capsular bag or in the sulcus." },
  "monobloc": { term: "single-piece IOL", def: "IOL made of a single piece of acrylic, with thick square-edged haptics, designed for the capsular bag and not for the sulcus (risk of UGH syndrome)." },
});
